def countQuadruples(N):
    count = 0
    squares = [i * i for i in range(1, N + 1)]
    for i in range(N):
        for j in range(i + 1, N):
            sum_sq = squares[i] + squares[j]
            for k in range(N):
                for l in range(k + 1, N):
                    if sum_sq == squares[k] + squares[l]:
                        count += 1
    return count
