import json

def read_json(json_data: str, key_path: str) -> any:
    """
    Reads a value from a JSON string using a dot-notation path with optional array indexing.

    Args:
        json_data (str): A JSON-formatted string.
        key_path (str): A path like "key1.key2[0]" to access nested values.

    Returns:
        any: The value at the specified path, or None if the path is invalid.
    """
    try:
        data = json.loads(json_data)
        keys = key_path.split('.')
        current = data

        for key in keys:
            if not key:
                return None

            if key.startswith('[') and key.endswith(']'):
                index = int(key[1:-1])
                if isinstance(current, list) and 0 <= index < len(current):
                    current = current[index]
                else:
                    return None
            elif isinstance(current, dict) and key in current:
                current = current[key]
            else:
                return None

        return current
    except (json.JSONDecodeError, ValueError, TypeError, KeyError, IndexError):
        return None
```

