def can_form_sticks(pieces, target_length):
    n = len(pieces)

    # Sort pieces in descending order for better pruning
    pieces.sort(reverse=True)

    # Memoization key: tuple of remaining pieces
    @lru_cache(maxsize=None)
    def backtrack(index, current_length, sticks_count):
        # If we've used all pieces
        if index == n:
            return current_length == 0 and sticks_count == 0

        # If current stick is complete, start a new one
        if current_length == 0:
            # Skip duplicate pieces to avoid redundant work
            if index < n and pieces[index] == pieces[index + 1]:
                return backtrack(index + 1, 0, sticks_count + 1)
            return backtrack(index + 1, 0, sticks_count + 1)

        # Try to add pieces to the current stick
        for i in range(index, n):
            if pieces[i] + current_length <= target_length:
                if backtrack(i + 1, current_length + pieces[i], sticks_count):
                    return True
            # Skip duplicate pieces to avoid redundant work
            if i < n - 1 and pieces[i] == pieces[i + 1]:
                continue

        return False

    return backtrack(0, 0, 0)
