            if s1 == s2:
                return True
            if sorted(s1) != sorted(s2):
                return False
            c1 = collections.Counter(s1)
            c2 = collections.Counter(s2)
            diff = [k for k in c1 if c1[k] != c2[k]]
            if len(diff) == 0:
                return True
            if len(diff) == 1:
                k = diff[0]
                if abs(c1[k] - c2[k]) == 1:
                    return True
            return False

        def can_swap_twice(s1, s2):
            if s1 == s2:
                return True
            if sorted(s1) != sorted(s2):
                return False
            c1 = collections.Counter(s1)
            c2 = collections.Counter(s2)
            diff = [k for k in c1 if c1[k] != c2[k]]
            if len(diff) == 0:
                return True
            if len(diff) == 1:
                k = diff[0]
                if abs(c1[k] - c2[k]) == 1:
                    return True
            if len(diff) == 2:
                k1, k2 = diff[0], diff[1]
                if abs(c1[k1] - c2[k1]) == 1 and abs(c1[k2] - c2[k2]) == 1:
                    return True
            return False

        n = len(nums)
        ans = 0
        for i in range(n):
            s1 = to_s(nums[i])
            for j in range(i + 1, n):
                s2 = to_s(nums[j])
                if can_swap_twice(s1, s2):
                    ans += 1
