                            w1, w2, w3, w4 = pizzas[idx * 4 + i], pizzas[idx * 4 + j], pizzas[idx * 4 + k], pizzas[idx * 4 + l]
                            w1, w2, w3, w4 = sorted([w1, w2, w3, w4])
                            if day % 2 == 1:
                                gain = w4
                            else:
                                gain = w3
                            max_gain = max(max_gain, gain + solve(idx + 1, day + 1))

            memo[(idx, day)] = max_gain
            return max_gain

