class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        if not edges:
            return -1

        edges.sort(key=lambda x: x[2])

        def can_reach(max_w: int) -> bool:
            adj = [[] for _ in range(n)]
            for u, v, w in edges:
                if w <= max_w:
                    adj[u].append(v)

            for i in range(1, n):
                if len(adj[i]) > threshold:
                    return False

            visited = [False] * n
            stack = [0]
            visited[0] = True
            while stack:
                u = stack.pop()
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)

            return all(visited)

        left, right = 0, 10**6
        while left <= right:
            mid = (left + right) // 2
            if can_reach(mid):
                right = mid - 1
            else:
                left = mid + 1

        return left if left <= 10**6 else -1
