def min_cost(cost, m, n):
    if m < 0 or n < 0 or m >= len(cost) or n >= len(cost[0]):
        return float('inf')

    dp = [[float('inf')] * len(cost[0]) for _ in range(len(cost))]
    dp[0][0] = cost[0][0]

    for i in range(len(cost)):
        for j in range(len(cost[0])):
            if i == 0 and j == 0:
                continue
            if i == 0:
                dp[i][j] = dp[i][j-1] + cost[i][j]
            elif j == 0:
                dp[i][j] = dp[i-1][j] + cost[i][j]
            else:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + cost[i][j]

    return dp[m][n]
```

