    for i in range(1, m + 1):
        dp[i][0] = dp[i - 1][0] + cost[i - 1][0]
    for j in range(1, n + 1):
        dp[0][j] = dp[0][j - 1] + cost[0][j - 1]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            dp[i][j] = cost[i - 1][j - 1] + min(dp[i - 1][j], dp[i][j - 1])
    return dp[m][n]
