def common_prefix(strings, k):
    if not strings:
        return ""

    # Use the first string as reference, but only up to k characters
    prefix = strings[0][:k]

    for s in strings[1:]:
        # Compare prefix with current string character by character
        for i in range(min(len(prefix), len(s))):
            if prefix[i] != s[i]:
                # Found mismatch, truncate prefix
                prefix = prefix[:i]
                break
        if not prefix:
            return ""

    return prefix

