```python
def find_longest_repeating_subseq(s: str) -> int:
    n = len(s)
    if n == 0:
        return 0

    # dp[i][j] represents the length of the longest repeating subsequence
    # where the two subsequences don't have same string characters at same positions
    # We use a 2D array where dp[i][j] stores the length of the longest
    # repeating subsequence ending at indices i and j in the original string
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(i + 1, n):
            if s[i] == s[j] and i != j:
                # If characters match and are at different positions
                if i != j:
                    dp[i][j] = dp[i-1][j-1] + 1 if i > 0 and j > 0 else 1
                else:
                    dp[i][j] = 0

    # Find the maximum value in the dp table
    max_len = 0
    for i in range(n):
        for j in range(i + 1, n):
            max_len = max(max_len, dp[i][j])

    return max_len
```

