def extract_min_max(t, k):
    if k <= 0:
        return tuple()
    if k >= len(t):
        return tuple(sorted(t))

    min_heap = []
    max_heap = []

    for num in t:
        if len(min_heap) < k:
            heapq.heappush(min_heap, num)
        else:
            if num < min_heap[0]:
                heapq.heapreplace(min_heap, num)

        if len(max_heap) < k:
            heapq.heappush(max_heap, -num)
        else:
            if num > -max_heap[0]:
                heapq.heapreplace(max_heap, -num)

    min_elements = sorted([x for x in min_heap])
    max_elements = sorted([-x for x in max_heap])

    return tuple(min_elements + max_elements)
