def min_flip_to_make_string_alternate(s: str) -> int:
    n = len(s)
    if n == 0:
        return 0

    # Count flips needed to make string start with '0' (pattern: 010101...)
    flips_start_0 = 0
    for i in range(n):
        expected = '0' if i % 2 == 0 else '1'
        if s[i] != expected:
            flips_start_0 += 1

    # Count flips needed to make string start with '1' (pattern: 101010...)
    flips_start_1 = 0
    for i in range(n):
        expected = '1' if i % 2 == 0 else '0'
        if s[i] != expected:
            flips_start_1 += 1

    return min(flips_start_0, flips_start_1)

