def ncr_modp(n, r, p):
    if r < 0 or r > n:
        return 0
    if r == 0 or r == n:
        return 1
    if r > n // 2:
        r = n - r

    numerator = 1
    for i in range(r):
        numerator = (numerator * (n - i)) % p

    denominator = 1
    for i in range(r):
        denominator = (denominator * (i + 1)) % p

    return (numerator * pow(denominator, p - 2, p)) % p
```

