def is_subset_sum(nums, target_sum, max_sum):
    n = len(nums)
    dp = [[False] * (max_sum + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = True
    for i in range(1, n + 1):
        for j in range(max_sum + 1):
            dp[i][j] = dp[i - 1][j]
            if nums[i - 1] <= j:
                dp[i][j] = dp[i][j] or dp[i - 1][j - nums[i - 1]]
    return dp[n][target_sum]
```

