def is_subset_sum(nums, target, memo=None):
    if memo is None:
        memo = {}

    key = (tuple(sorted(nums)), target)
    if key in memo:
        return memo[key]

    if target == 0:
        return True
    if not nums or target < 0:
        return False

    # Try including the first element
    if nums[0] <= target:
        if is_subset_sum(nums[1:], target - nums[0], memo):
            memo[key] = True
            return True

    # Try excluding the first element
    if is_subset_sum(nums[1:], target, memo):
        memo[key] = True
        return True

    memo[key] = False
    return False

