import heapq

def heap_queue_smallest(numbers, k):
    if k <= 0:
        return []
    if k >= len(numbers):
        return sorted(numbers)

    # Create a min-heap from the list
    heapq.heapify(numbers)

    # Extract the smallest k elements
    result = [heapq.heappop(numbers) for _ in range(k)]

    return result
