def find_Min_Sum(arr1, arr2, k):
    """
    Find the minimum sum of absolute differences of two arrays.
    The function considers all possible subarrays of length k from both arrays.
    """
    n = len(arr1)
    m = len(arr2)

    if k > n or k > m:
        return float('inf')

    min_sum = float('inf')

    for i in range(n - k + 1):
        for j in range(m - k + 1):
            current_sum = 0
            for p in range(k):
                current_sum += abs(arr1[i + p] - arr2[j + p])
            min_sum = min(min_sum, current_sum)

    return min_sum if min_sum != float('inf') else 0
```

