def max_sum_of_three_consecutive(nums):
    n = len(nums)
    if n < 3:
        return sum(nums)

    max_sum = 0
    current_sum = 0

    for i in range(n):
        current_sum += nums[i]

        if i >= 2:
            if nums[i-2] + nums[i-1] + nums[i] == 0:
                current_sum = 0
            else:
                current_sum += nums[i]

        if current_sum > max_sum:
            max_sum = current_sum

    return max_sum
