def max_sum_of_three_consecutive(arr, n):
    if n < 0:
        return 0
    if n == 0:
        return 0
    if n == 1:
        return arr[0]
    if n == 2:
        return arr[0] + arr[1]

    dp = [0] * (n + 1)
    dp[1] = arr[0]
    dp[2] = arr[0] + arr[1]

    for i in range(3, n + 1):
        dp[i] = max(
            dp[i-1] + arr[i-1],
            dp[i-2] + arr[i-1],
            dp[i-3] + arr[i-1]
        )

    return dp[n]

