def generate_matrix(n):
    if n == 0:
        return []

    matrix = [[0] * n for _ in range(n)]
    top, bottom = 0, n - 1
    left, right = 0, n - 1
    current = 1

    while current <= n * n:
        for i in range(left, right + 1):
            matrix[top][i] = current
            current += 1
        top += 1
        if top == bottom:
            break
        for i in range(top, bottom + 1):
            matrix[i][right] = current
            current += 1
        right -= 1
        if right == left:
            break
        for i in range(bottom, top - 1, -1):
            matrix[i][left] = current
            current += 1
        left += 1
        if left == right:
            break

    return matrix
```

