    for i in range(len(tuples)):
        for j in range(i + 1, len(tuples)):
            diff = abs(tuples[i][0] - tuples[j][0])
            diff = min(diff, abs(tuples[i][1] - tuples[j][1]))
            min_diff = min(min_diff, diff)
    return min_diff
