def coin_change(coins, target, target_count):
    memo = {}

    def dp(index, count):
        if index == len(coins):
            return 0
        if count == 0:
            return 0
        if index in memo:
            return memo[index]

        if coins[index] > count:
            return dp(index + 1, count)
        else:
            res = dp(index + 1, count)
            res += dp(index + 1, count - coins[index])
            memo[index] = res
            return res

    return dp(0, target_count)
```

