def int_to_roman(num):
    if num == 0:
        return ""
    roman_map = {
        1: "I",
        5: "V",
        10: "X",
        50: "L",
        100: "C",
        500: "D",
        1000: "M"
    }
    result = []
    for value, symbol in sorted(roman_map.items(), key=lambda x: x[0], reverse=True):
        while num >= value:
            result.append(symbol)
            num -= value
    return "".join(result)
```

