def maximum_segments(n, a, b, c, target):
    max_segments = 0
    for i in range(target + 1):
        for j in range(target + 1):
            for k in range(target + 1):
                if i * a + j * b + k * c <= n:
                    max_segments = max(max_segments, i + j + k)
    return max_segments
```

```python
def maximum_segments(n, a, b, c):
    max_segments = 0
    for i in range(n // a + 1):
        for j in range((n - i * a) // b + 1):
            k = (n - i * a - j * b) // c
            max_segments = max(max_segments, i + j + k)
    return max_segments
```

